      console.log(`星${selectedScore}をセット`);

      // 1. モーダル内の隠しフォームとテキスト値を同期
      hiddenScore.value = selectedScore;
      ratingValue.textContent = selectedScore;

      // 2. 既存のマウスアウト時の表示ロジック（index）と同期させる
      index = i;

